-- Generated by ETLIR from a validated Pipeline Semantic Model.
COPY (
  WITH
  "read_orders" AS (
    SELECT *
    FROM read_csv('data/orders.csv',
      header = true,
      columns = {'order_id': 'BIGINT', 'customer_id': 'VARCHAR', 'status': 'VARCHAR', 'gross_amount': 'DOUBLE', 'discount_amount': 'DOUBLE'})
  ),
  "keep_completed" AS (
    SELECT *
    FROM "read_orders"
    WHERE ("status" = 'COMPLETE')
  ),
  "calculate_net" AS (
    SELECT
      *,
      ("gross_amount" - "discount_amount") AS "net_amount"
    FROM "keep_completed"
  )
  SELECT *
  FROM "calculate_net"
)
TO 'build/orders.parquet'
(FORMAT PARQUET);
